def _crop_tiles(size):
    h = HALF[size - 1]
    out = []
    for dx in range(-h, h + 1):
        for dz in range(-h, h + 1):
            ax, az = abs(dx), abs(dz)
            if ax == h and az == h:
                continue
            if ax == h or az == h or (ax <= 1 and az <= 1):
                continue
            out.append((dx, dz))
    return out


