# "" = nothing done (no file - loadCfg writes the 0.4.9 default with the marker -, marker already there, or a failure: WARN, file untouched,
# retried at the next start); else the INFO lines joined by \n. The kit's HOME / LOG / history / change log are set by setup() first.
M(smig49, r"""
public static synchronized String run(java.nio.file.Path f) {
  LAST = "";
  if (f == null) return "";
  try {
    if (!java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) return "";
    byte[] old = java.nio.file.Files.readAllBytes(f);
    Object[] r = update(new String(old, "ISO-8859-1"));
    if (r == null) return "";
    byte[] data = ((String) r[0]).getBytes("ISO-8859-1");
    String[] moved = (String[]) r[3];
    if (!sameAfter(old, data, moved)) {
      @PKG@.ShCfg.warn("config.properties NOT updated for SkyyShards 0.4.9 (+3 % a sub-upgrade level): the update would change more than those lines (the file is used as it is; the next start tries again)");
      return "";
    }
    int fi = fileIdx();
    if (fi < 0) return "";
    @PKG@.CfgHist.snapshot(fi, old, @PKG@.CfgHist.stamp(), WHO, "before the 0.4.9 update (+3 % a sub-upgrade level)");
    if (!saved(fi, old)) {
      @PKG@.ShCfg.warn("config.properties NOT updated for SkyyShards 0.4.9 (+3 % a sub-upgrade level): the old file could not be kept in config-history (the file is used as it is; the next start tries again)");
      return "";
    }
    @PKG@.CfgRows.atomicWrite(f, data);
    String[] rows = (String[]) r[1];
    StringBuilder ch = new StringBuilder();
    for (int i = 0; i + 2 < rows.length; i += 3) {
      @PKG@.CfgLog.enqueue(@PKG@.CfgLog.now() + "\t" + WHO + "\t-\tupdate\t" + rows[i] + "\t" + rows[i + 1] + "\t" + rows[i + 2] + "\tok");
      ch.append(ch.length() == 0 ? "" : ", ").append(rows[i]).append(' ').append(rows[i + 1]).append(" -> ").append(rows[i + 2]);
    }
    if (rows.length > 0) @PKG@.CfgLog.flush();
    String msg = "config.properties updated for SkyyShards 0.4.9 (shards are the primary late-game source: +3 % output a sub-upgrade level, was 0.5 %): " + (rows.length == 0 ? "no setting line held the old default" : ch.toString() + " (the old file is in config-history; Server Setup -> Shards -> Changes can undo each)") + " [marker " + MK + " added, runs once]";
    @PKG@.ShCfg.info(msg);
    StringBuilder all = new StringBuilder(msg);
    String[] notes = (String[]) r[2];
    for (int i = 0; i < notes.length; i++) {
      @PKG@.ShCfg.info("config.properties: " + notes[i]);
      all.append('\n').append(notes[i]);
    }
    LAST = all.toString();
    return LAST;
  } catch (Throwable t) {
    @PKG@.ShCfg.warn("could not update config.properties for SkyyShards 0.4.9 (+3 % a level; the file is used as it is): " + t);
    return "";
  }
}""")
