# 0.3: one purchase on shard kd (caller holds ShStore.LOCK): `item` x qty taken first (counted), then coins (items back when they fail),
# then key = val written (a refused save undoes it and refunds both). null = bought, else the refusal line. tag / what name it in collect.log
M(core, r"""
public static String purchase(java.util.UUID u, String k, int kd, java.util.Properties p, @IC@[] cs, String item, long qty, long coins, String key, String val, String tag, String what) {
  long have = @PKG@.ShInv.count(cs, item);
  String nm = @PKG@.ShTotem.pretty(item);
  if (have < qty) return "-You need " + qty + " " + nm + " (you have " + have + ").";
  long purse = @PKG@.ShPay.coins(u);
  if (coins > 0L && purse >= 0L && purse < coins) return "-You need " + @PKG@.ShCfg.num(coins) + " coins (you have " + @PKG@.ShCfg.num(purse) + ").";
  @PKG@.ShMath.settleAll(kd, p, now());   // production up to now at the old numbers
  java.util.ArrayList kept = new java.util.ArrayList();   // fix (critic shards03): exact refunds of stacks with data
  long got = @PKG@.ShInv.take2(cs, item, qty, kept);
  if (got < qty) { @PKG@.ShInv.giveBack(cs, item, got, kept); return "-The " + nm + " could not be taken - nothing was bought."; }
  if (!@PKG@.ShPay.takeCoins(u, coins)) { long r = @PKG@.ShInv.giveBack(cs, item, got, kept); @PKG@.ShStore.log(u + " " + k + " " + tag + " refund " + r + " of " + got + " " + item); return "-The coins could not be taken - your " + nm + " is back."; }
  java.util.Properties old = new java.util.Properties();
  old.putAll(p);
  p.setProperty(key, val);
  String e = @PKG@.ShStore.save(k, p);
  if (e != null) {   // fix (critic): not saved = undone + everything paid goes back
    p.clear(); p.putAll(old);
    long ri = @PKG@.ShInv.giveBack(cs, item, got, kept);
    boolean rc = @PKG@.ShPay.addCoins(u, coins);
    @PKG@.ShStore.log(u + " " + k + " " + what + " SAVE FAILED " + e + " - refund " + ri + " of " + got + " " + item + ", coins " + (rc ? coins : 0L) + " of " + coins);
    @PKG@.ShCfg.warn(tag + " not saved, refunded: " + e);
    return "-The upgrade could not be saved - your " + nm + (rc ? " and coins are" : " is") + " back." + (rc ? "" : " Ask an admin about the " + @PKG@.ShCfg.num(coins) + " coins (collect.log).");
  }
  @PKG@.ShStore.log(u + " " + k + " " + what + " paid " + coins + " coins + " + got + " " + item + @PKG@.ShInv.keptText(kept));
  return null;
}""")
