# 0.4.7 (Skyy 2026-10-23 "tier up should work in the totem pole"): the 0.4 ShCore.upgrade line ("Totems tier up at the ... Totem Bench") is
# gone - the totem page tiers up the placed totem itself (ShCore.tierUpPlaced, after the bench tier-up below)
# ---- crafting (Craft tab). A recipe "Item:qty,Item:qty;coins" -> Object[]{ String[] ids, long[] qty, Long coins } or null (bad / empty)
# fix2 (critic shards03 2nd round): the same id named twice is ONE row (quantities added, first place kept), so the per-row item check
# counts the sum and a refund (giveBack per id) can never hand the kept stacks back twice
M(core, r"""
public static Object[] recipe(String txt) {
  if (txt == null || txt.trim().length() == 0) return null;
  try {
    String t = txt.trim();
    long coins = 0L;
    int sc = t.indexOf(';');
    if (sc >= 0) { String c = t.substring(sc + 1).trim(); if (c.length() > 0) coins = Long.parseLong(c); t = t.substring(0, sc).trim(); }
    if (coins < 0L) return null;
    String[] a = t.length() == 0 ? new String[0] : t.split(",");
    String[] ids0 = new String[a.length];
    long[] q0 = new long[a.length];
    int m = 0;
    for (int i = 0; i < a.length; i++) {
      String[] b = a[i].trim().split(":");
      if (b.length != 2 || b[0].trim().length() == 0) return null;
      String id = b[0].trim();
      long n = Long.parseLong(b[1].trim());
      if (n < 1L || n > 100000L) return null;
      int at = -1;
      for (int j = 0; j < m; j++) if (ids0[j].equals(id)) at = j;
      if (at >= 0) { q0[at] += n; if (q0[at] > 100000L) return null; }
      else { ids0[m] = id; q0[m] = n; m++; }
    }
    String[] ids = new String[m];
    long[] q = new long[m];
    for (int i = 0; i < m; i++) { ids[i] = ids0[i]; q[i] = q0[i]; }
    if (ids.length == 0 && coins == 0L) return null;
    return new Object[] { ids, q, Long.valueOf(coins) };
  } catch (Throwable x) { return null; }
}""")
# rebirths of a profile (SkyyRebirth rebirth:fn:count): -2 = still loading, 0 = none / no SkyyRebirth
