M(sweep, r"""
public static int rescueKind(String k, double x, double y, java.util.UUID u, long now) {
  if (y >= RESCUE_Y || k == null) return -1;
  if (u != null) { Object l = RESCUED.get(u); if (l instanceof Long && now - ((Long) l).longValue() < 4000L) return -1; }
  java.util.Properties p = @PKG@.ShStore.get(k);
  if (p == null) return -1;
  int at = @PKG@.ShKind.ofX(x);
  int kd = -2;
  @PKG@.ShStore.LOCK.lock(); try {
    if (ready(p, at)) kd = at;
    else if (ready(p, @PKG@.ShKind.FARM)) kd = @PKG@.ShKind.FARM;
    else for (int i = 0; i < @PKG@.ShKind.N && kd < 0; i++) if (ready(p, i)) kd = i;
  } finally { @PKG@.ShStore.LOCK.unlock(); }
  if (u != null) RESCUED.put(u, Long.valueOf(now));
  return kd;
}""")
