# 0.4.7: the Tier up rows of the selected placed totem f (onPad form): 7 = "Tier up: <cost>" (green = you can), 8-9 = each ingredient
# "N Item (you have N)" (inventory + bags; Style Guide 15 requirement colours); a bench below the next tier says so (red)
M(page, r"""
public void tierRows(java.util.Properties p, @IC@[] cs, int kd, String[] f, int ti, long now) {
  int t = @PKG@.ShTotem.tierOf(f[1]);
  if (t >= 5) { this.dTx[7] = "Tier up: highest tier reached."; this.dCol[7] = "@GOLD@"; return; }
  if (ti < 0 || p == null) return;
  int bt = @PKG@.ShCore.benchTier(kd, p, now);
  int cap = @PKG@.ShCfg.benchCap(bt);
  String c = @PKG@.ShTotem.costAt(kd, @PKG@.ShTotem.ITEMS[ti], @PKG@.ShTotem.doc(f, now).toJson());
  Object[] rc = null;
  if (!c.startsWith("err:")) rc = @PKG@.ShCore.recipe(c);
  if (rc == null) { this.dTx[7] = "Tier up: the cost setting is broken - ask an admin."; this.dCol[7] = "@BAD@"; return; }
  this.dTx[7] = "Tier up: " + costWords(c);
  if (t + 1 > cap) {
    this.dCol[7] = "@BAD@";
    this.dTx[8] = "Your Totem Bench " + @PKG@.ShTotem.ROMAN[bt - 1] + " stops at " + @PKG@.ShTotem.LADDER[cap - 1] + " - upgrade it first.";
    this.dCol[8] = "@BAD@";
    return;
  }
  String[] ids = (String[]) rc[0];
  long[] q = (long[]) rc[1];
  boolean all = true;
  for (int i = 0; i < ids.length && 8 + i < this.dTx.length; i++) {
    long h = cs == null ? -1L : @PKG@.ShCore.haveAll(this.me, cs, ids[i]);
    this.dTx[8 + i] = @PKG@.ShCfg.num(q[i]) + " " + @PKG@.ShTotem.pretty(ids[i]) + " (you have " + (h < 0L ? "?" : @PKG@.ShCfg.num(h)) + ")";
    boolean ok = h >= q[i];
    this.dCol[8 + i] = ok ? "@GOOD@" : "@BAD@";
    if (!ok) all = false;
  }
  this.dCol[7] = all ? "@GOOD@" : "@BAD@";
}""".replace("@GOOD@", GOOD).replace("@BAD@", BAD).replace("@GOLD@", GOLD))
# the Totems tab / the totem page texts (under the ShStore lock, settled already): the selected island, its totems on their pads, the
